// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 setVal, uint256 collectAmt) public {
        // Ensure setVal is within a reasonable range (e.g., not overflow)
        vm.assume(setVal <= type(uint256).max / 2);
        // Ensure collectAmt is not excessively large
        vm.assume(collectAmt <= type(uint256).max / 2);

        // Optionally, we can call SetMinSum (but it can only be called before Initialized)
        // To keep it general, we either call SetMinSum or not; we choose to call it.
        // But the bug breaks this behavior: in the bug, MinSum is always set to 0.
        // So the rule: after any Collect call, MinSum equals the last value set by SetMinSum.
        // Since we call SetMinSum only once, it should equal that value.
        c.SetMinSum(setVal);
        c.Initialized();

        // Drive a call to Collect
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmt));
        // If revert, it's fine; we just assert on state
        // The assertion: MinSum equals setVal (original C) or equals 0 (buggy)
        assertTrue(c.MinSum() == setVal);
    }
}

